require __DIR__.'/inc/bootstrap.php';
header('Content-Type: application/xml; charset=utf-8');$base=(isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost');$services=$db->query('SELECT slug FROM services WHERE active=1')->fetchAll();$paths=['','services','about','contacts'];foreach($services as $service)$paths[]='services/'.$service['slug'];echo '<?xml version="1.0" encoding="UTF-8"?>' . "\n";echo '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">';foreach($paths as $path){foreach(['ru','kk'] as $locale){$url=$base.site_path($path,$locale);echo '<url><loc>'.h($url).'</loc><changefreq>'.($path===''?'weekly':'monthly').'</changefreq><priority>'.($path===''?'1.0':'0.7').'</priority>';echo '<xhtml:link rel="alternate" hreflang="ru-KZ" href="'.h($base.site_path($path,'ru')).'"/><xhtml:link rel="alternate" hreflang="kk-KZ" href="'.h($base.site_path($path,'kk')).'"/></url>';}}echo '</urlset>';
